"""Swift-only review treatment. Does not write shared assets or any other report."""
from pathlib import Path
from bs4 import BeautifulSoup
from html import escape as esc
from datetime import date
import json
B=Path(__file__).resolve().parent;D=B/'dist'
def fmt(d):return date.fromisoformat(d).strftime('%-d %b %Y')
def amount(n):
 t=str(round(n));head=t[:-3];groups=[]
 while head:groups.insert(0,head[-2:]);head=head[:-2]
 return '₹'+(','.join(groups)+',' if groups else '')+t[-3:]
def details(items,cls=''):
 return f'<dl class="evidence-facts {cls}">'+''.join(f'<div><dt>{a}</dt><dd>{b}</dd></div>' for a,b in items)+'</dl>'
def question(text,copy='',link=None):return '<aside class="seller-prompt"><span>Ask the seller</span><p>“'+text+'”</p>'+('<small>'+copy+'</small>' if copy else '')+(f'<a href="{link[0]}">{link[1]}</a>' if link else '')+'</aside>'
def chapter(id,num,label,title,intro,body,prompt,source):
 title=title.replace('<br>',' <br>')
 return f'<section class="swift-chapter" id="{id}"><div class="chapter-heading"><p class="chapter-label"><span>{num:02}</span>{label}</p><h2>{title}</h2><p>{intro}</p></div><div class="chapter-evidence"><div class="evidence-surface" data-swift-reveal>{body}</div><p class="evidence-source">{source} · {fmt("2026-11-24")}</p>{prompt}</div></section>'
def build_swift_report():
 c=next(c for c in json.loads((D/'cars.json').read_text())['cars'] if c['id']=='swift');raw=BeautifulSoup((B/'data/swift-report-before.html').read_text(),'html.parser');
 for el in raw.select('.site-header .header-action,.site-header .mobile-report'):el.decompose()
 header=str(raw.header);footer=str(raw.footer)
 photos=[dict(p,label={'Right Front Diagonal':'Front right','Right Back Diagonal':'Rear right','Dashboard':'Dashboard','Left Front Diagonal':'Front left'}.get(p['view'],p['view'])) for p in c['photos']]
 photo_fallback='<noscript><p class="photo-fallback">'+ ' · '.join(f'<a href="{p["src"]}">{p["label"]}</a>' for p in photos)+'</p></noscript>'
 thumbnails=''.join(f'<button type="button" class="photo-thumb" data-photo-index="{i}" aria-label="Show {p["label"].lower()} photo" aria-pressed="{str(i==0).lower()}"><img src="{p["src"]}" alt="" width="210" height="140"><span>{p["label"]}</span></button>' for i,p in enumerate(photos))
 gallery=f'''<section id="photos" class="photo-chapter" aria-labelledby="photo-heading"><div class="photo-heading"><h2 id="photo-heading">Vehicle photos</h2><span>4 views</span></div><div class="gallery-selected"><button type="button" class="gallery-open" aria-label="Open front right photo in full screen"><img id="selected-photo" src="{photos[0]['src']}" alt="Maruti Suzuki Swift LXI — front right view" width="1200" height="800"><span class="enlarge-label">View full screen<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M12 3h5v5M17 3l-6 6M8 17H3v-5M3 17l6-6"/></svg></span></button><div class="photo-caption"><span id="selected-photo-caption">Front right</span><span id="selected-photo-count" aria-live="polite">1 of 4</span></div></div><div class="photo-thumbnails" role="group" aria-label="Choose a vehicle photo">{thumbnails}</div>{photo_fallback}</section>'''
 cover=f'''<div class="report-toolbar"><a href="index.html">Back to VIB</a><div><button type="button" class="print-button">Print report</button></div></div><header class="report-cover"><div class="cover-copy"><p class="report-kicker">Vehicle history report</p><h1>Maruti Suzuki <br>Swift <span>LXI</span></h1><p class="cover-specs">2020 · Petrol · Manual</p><p class="cover-registration">{c['registration']}<span>{c['region']}</span></p><dl class="cover-facts"><div><dt>Seller’s reading</dt><dd>{c["declaredKm"]:,} <span>km</span></dd></div><div><dt>Ownership</dt><dd>First owner</dd></div><div><dt>Service invoices</dt><dd>6 on record</dd></div></dl><p class="report-number">24 Nov 2026 · {c['reportId']}</p></div>{gallery}</header>'''
 overview=f'''<section class="report-overview" aria-labelledby="overview-heading"><div class="condition-snapshot"><span>Condition score</span><div class="condition-value"><strong>{c["score"]["value"]}</strong><span>/100</span></div><div class="condition-track" aria-hidden="true"><span style="width:{c['score']['value']}%"></span></div><h2>{esc(c["score"]["label"])}</h2><p>Read the evidence.<br>Inspect before deciding.</p></div><div class="priority-findings"><p class="report-kicker">Before you decide</p><h2 id="overview-heading">Three things to look at closely.</h2><a href="#mileage"><span><b>The mileage records conflict.</b><small>The seller’s reading is below the last service entry.</small></span><strong>{c["services"][-1]["km"]-c["declaredKm"]:,} <small>km</small></strong></a><a href="#finance"><span><b>A lender entry is active.</b><small>Ask for the closure documents before transfer.</small></span><strong class="finding-word">Documents needed</strong></a><a href="#claims"><span><b>A repair claim is on record.</b><small>Review the invoice and inspect the repair.</small></span><strong>{amount(c["claim"]["amount"])}</strong></a></div></section>'''
 navitems=[('photos','Photos'),('mileage','Mileage'),('ownership','Ownership'),('finance','Finance'),('claims','Repairs'),('challans','Documents'),('valuation','Price'),('timeline','Timeline')]
 links=''.join(f'<a href="#{id}">{label}</a>' for id,label in navitems)
 navigation=f'<nav class="chapter-nav" aria-label="Report chapters">{links}</nav><details class="chapter-menu"><summary>Jump to a chapter<span>8 chapters</span></summary><nav aria-label="Mobile report chapters">{links}</nav></details>'
 from swift_mileage import render_mileage
 graph,readings=render_mileage(c)
 visits=''.join(f'<li><div class="visit-meta"><time datetime="{r["date"]}">{fmt(r["date"])}</time><strong>{r["km"]:,} km</strong></div><div><h4>{r["work"]}</h4><p>{esc(r["workshop"])}</p><span>{r["id"]}</span></div><b>{amount(r["amount"])}</b></li>' for r in reversed(c['services']))
 graph+=f'<details class="service-invoices" open><summary>Service invoices<span>6 visits</span></summary><ol>{visits}</ol></details>'
 mileage=chapter('mileage',2,'Mileage & service','Do the readings tell<br>the same story?','The dates move forward. The later declaration is lower. Compare the original documents before drawing a conclusion.',graph,question('Can we check the service invoices against the odometer?',link=('guide-mileage.html','Read the mileage guide')),'Service invoices and seller declaration')
 ownbody='<div class="surface-heading"><h3>Identity & ownership</h3><span class="record-state">First owner</span></div>'+details([('First registered',fmt(c['registeredOn'])),('Registration region',c['region']),('Registration',c['registration']),('Body style',c['bodyType']),('Fuel / transmission','Petrol / Manual'),('Usage',c['usage']),('Modifications',c['modifications']),('Registration valid until',fmt(c['validUntil']))],'facts-grid')+'<p class="surface-footnote">Factory equipment and engine specifications have not been verified in this record set.</p>'
 ownership=chapter('ownership',3,'Identity & ownership','Make sure the details<br>match the car.','Start with the registration certificate. Match the vehicle details and the seller’s ownership documents.',ownbody,question('Do these details match your registration certificate?'),'Registration record')
 financebody='<div class="finance-feature"><div><span class="record-state attention">Active lender entry</span><h3>Ask for the closure letter.</h3><p>The entry records a lender’s interest in the vehicle. It does not show the amount owed.</p></div><img src="assets/030ff.webp" alt="" width="160" height="160" loading="lazy"></div>'+details([('Closure documents','Not provided'),('Loan balance','Unavailable'),('Repayment status','Unavailable'),('Before transfer','Verify the current lender entry')])
 finance=chapter('finance',4,'Finance & transfer','An active entry needs<br>a follow-up.','Review the current registration record and lender documents before arranging the transfer.',financebody,question('Can we review the lender’s closure documents before transfer?',link=('guide-finance.html','Understand lender entries')),'Registration finance entry')
 claim=c['claim'];claimbody=f'<div class="claim-feature"><div><span>Repair claim · {fmt(claim["date"])}</span><strong>{amount(claim["amount"])}</strong><p>{claim["part"]}</p></div><span class="record-state">Settled</span></div>'+details([('Accident severity','Not established')])+'<div class="surface-divider"></div><div class="surface-heading"><h3>Insurance policy</h3><span class="record-state">Within recorded validity</span></div>'+details([('Cover type',c['policyType']),('Policy period','8 Jul 2026–'+fmt(c['policyUntil']))])+ '<details class="record-disclosure"><summary>What the repair record does not establish</summary>'+details([('Structural damage / total loss','Not assessed'),('Flood / airbag deployment','Not assessed'),('Engine / transmission repairs','No supporting record available')])+'</details>'
 claims=chapter('claims',5,'Insurance & repairs','See the record.<br>Understand the repair.','A claim amount does not establish accident severity or the car’s condition today. Read the invoice and inspect the work.',claimbody,question('Can we review the repair invoice and inspect the work?',link=('guide-inspection.html','Use records with an inspection')),'Policy and claim record set')
 challanrows=''.join(f'<li><div><h4>{r["offence"]}</h4><p>{fmt(r["date"])} · {r["id"]}</p></div><div><strong>{amount(r["amount"])}</strong><span>{r["status"]}</span></div></li>' for r in c['challans'])
 docbody=f'<div class="surface-heading"><h3>Challans</h3><span>2 unpaid entries</span></div><ul class="challan-list">{challanrows}</ul><div class="challan-total"><span>Unpaid total</span><strong>{amount(sum(r["amount"] for r in c["challans"]))}</strong></div><div class="surface-divider"></div><div class="surface-heading"><h3>Documents</h3></div>'+details([('Registration valid until',fmt(c['validUntil'])),('PUC valid until',fmt(c['pucUntil'])),('Road tax','Paid in the record')])
 challans=chapter('challans',6,'Challans & documents','Know what needs<br>attention before transfer.','Check the payment status and document dates with the seller. Records describe the position on their recorded date.',docbody,question('Can we verify payments and document validity together?'),'Challan and registration record set')
 low,high=c['priceRangeLakh'];listingrows=''.join(f'<div><time datetime="{r["date"]}">{fmt(r["date"])}</time><strong>{amount(r["amount"])}</strong><span>Asking price</span></div>' for r in c['askingPrices'])
 valuebody=f'<span class="value-label">Reference price range</span><h3 class="price-range">₹{low:.1f}–{high:.1f} <span>lakh</span></h3><p class="price-context">2020 Swift LXI · Gurugram</p><div class="price-range-line" aria-hidden="true"><span></span><span></span></div><p class="surface-footnote">A reference range for this sample, not a live valuation or an offer.</p><div class="surface-divider"></div><h4 class="subheading">Previous asking prices</h4><div class="asking-history">{listingrows}</div><p class="surface-footnote">Asking prices are not completed-sale prices. Comparable sales and peer ranking are unavailable.</p>'
 valuation=chapter('valuation',7,'Price context','Bring the records<br>to the price.','Read the service history, repair documents and inspection together before discussing the asking price.',valuebody,question('How does the asking price reflect the records and the car today?'),'Reference range and listing history')
 events=[(c['registeredOn'],'First registration',c['region'])]+[(r['date'],'Service invoice',f'{r["km"]:,} km · {r["work"]}') for r in c['services']]+[(claim['date'],'Repair claim settled',f'{amount(claim["amount"])} · {claim["part"]}')]+[(r['date'],'Asking price recorded',amount(r['amount'])) for r in c['askingPrices']]+[(r['date'],r['offence'],f'{amount(r["amount"])} · {r["status"]}') for r in c['challans']]+[(c['sellerDate'],'Seller mileage declaration',f'{c["declaredKm"]:,} km')]
 timeline='<ol class="swift-timeline">'+''.join(f'<li><time datetime="{d}">{fmt(d)}</time><div><h3>{h}</h3><p>{copy}</p></div></li>' for d,h,copy in sorted(events,key=lambda r:r[0]))+'</ol>'
 timelinehtml=chapter('timeline',8,'The complete timeline','Read the dates<br>together.','The registration, service, repair and listing records in one sequence. Each event keeps its own date.',timeline,question('Can you help me fill in the gaps between these records?'),'Combined record set')
 coverage='<section class="report-coverage" id="coverage-gaps"><div><p class="report-kicker">Record coverage</p><h2>Know what is<br>still missing.</h2><p>Use the available records with the original documents, a physical inspection and a test drive.</p></div><div>'+details([('Theft / court / FIR / recalls','Coverage unavailable'),('Loan balance / repayment','Unavailable'),('Accident severity / current condition','Not assessed'),('Factory equipment / peer ranking','Not verified')])+ '<p class="sample-provenance">Sample report: histories, amounts and outcomes are fictional; the condition score is preset. Photos show a model-matched CARS24 reference car and do not verify this history. Retrieved 24 Nov 2026; capture dates are unavailable.</p></div></section>'
 end='<div class="swift-report-end"><div><span>End of report</span><h2>Ask better questions.<br>Then inspect the car.</h2></div><a href="index.html" class="report-button">Back to VIB</a></div>'
 dialog=f'''<dialog id="photo-viewer" class="swift-photo-viewer" aria-labelledby="photo-viewer-title"><div class="viewer-header"><div><h2 id="photo-viewer-title">Maruti Suzuki Swift LXI</h2><p>Vehicle photos</p></div><button type="button" class="viewer-close">Close photos<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m4 4 12 12M16 4 4 16"/></svg></button></div><figure><img id="viewer-photo" src="{photos[0]['src']}" alt="Maruti Suzuki Swift LXI — front right view" width="1200" height="800"><figcaption id="viewer-caption">Front right</figcaption></figure><div class="viewer-controls"><button type="button" class="viewer-previous">Previous photo</button><p id="viewer-position" aria-live="polite">1 of 4</p><button type="button" class="viewer-next">Next photo</button></div></dialog>'''
 payload=json.dumps({'photos':[{'src':p['src'],'label':p['label']} for p in photos],'readings':readings},ensure_ascii=False).replace('</','<\\/')
 html=f'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0a1f36"><meta name="description" content="Read the 2020 Swift LXI sample report: vehicle photos, dated mileage and service records, ownership, finance, repair history and the questions to ask."><title>2020 Swift LXI — VIB vehicle history report</title><link rel="icon" href="assets/85ad8.svg"><link rel="preload" href="assets/plex-regular.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="base.css"><link rel="stylesheet" href="swift-report.css"><script src="sample-router.js"></script><script src="app.js" defer></script><script src="assets/gsap.min.js" defer></script><script src="assets/ScrollTrigger.min.js" defer></script><script src="motion.js" defer></script><script src="swift-report.js" defer></script><noscript><style>.print-button,.reading-explorer,.journey-controls,.enlarge-label{{display:none}}.photo-thumb{{pointer-events:none}}</style></noscript></head><body class="swift-report-page"><a class="skip" href="#main">Skip to content</a>{header}<main id="main"><div class="wrap swift-report">{cover}{overview}{navigation}{mileage}{ownership}{finance}{claims}{challans}{valuation}{timelinehtml}{coverage}{end}</div></main>{footer}{dialog}<script id="swift-report-data" type="application/json">{payload}</script></body></html>'''
 (D/'sample-swift.html').write_text(html)
 # The generic sample entry rotates with JavaScript and uses this same Swift as its no-script fallback.
 (D/'sample.html').write_text(html)
if __name__=='__main__':build_swift_report();print('Built Swift review report only.')
